#!/usr/bin/env node
// Generate iso/apps/chromium/tokens.css from the vendored frozen contract.
//
// The page must not carry hand-typed colours: it links the generated file and
// reads custom properties. `--check` exits 1 if the committed CSS is stale, so
// a contract change that was not regenerated fails the ISO check.
import fs from "node:fs";
import path from "node:path";
import url from "node:url";

const HERE = path.dirname(url.fileURLToPath(import.meta.url));
const ISO = path.resolve(HERE, "..");
const TOKENS = path.join(ISO, "contracts", "tokens.json");
const OUT = path.join(ISO, "apps", "chromium", "tokens.css");

const tokens = JSON.parse(fs.readFileSync(TOKENS, "utf8"));
const names = Object.keys(tokens);
if (!names.length) {
  console.error("tokens: the frozen contract is empty");
  process.exit(2);
}
for (const [name, value] of Object.entries(tokens)) {
  if (!/^#[0-9A-Fa-f]{6}$/.test(value)) {
    console.error(`tokens: ${name} is not a hex colour: ${value}`);
    process.exit(2);
  }
}

const lines = [
  "/* GENERATED by iso/tools/tokens_to_css.mjs from iso/contracts/tokens.json.",
  "   Do not edit by hand: change the contract (boss order) and regenerate. */",
  ":root {",
];
for (const name of names) lines.push(`  --meta-${name}: ${tokens[name]};`);
lines.push(
  "",
  "  /* derived here, so no page ever hand-mixes a colour */",
  "  --meta-bg: var(--meta-black);",
  "  --meta-panel: color-mix(in srgb, var(--meta-white) 7%, var(--meta-black));",
  "  --meta-text: var(--meta-white);",
  "  --meta-dim: color-mix(in srgb, var(--meta-white) 62%, var(--meta-black));",
  "  --meta-hairline: color-mix(in srgb, var(--meta-white) 14%, var(--meta-black));",
  "  --meta-accent: var(--meta-blue);",
  "}",
  "",
);
const body = lines.join("\n");

if (process.argv.includes("--check")) {
  let have = "";
  try { have = fs.readFileSync(OUT, "utf8"); } catch {}
  if (have !== body) {
    console.error("tokens.css is stale: run `node iso/tools/tokens_to_css.mjs`");
    process.exit(1);
  }
  console.log("tokens.css is current");
  process.exit(0);
}
fs.writeFileSync(OUT, body);
console.log("wrote " + path.relative(ISO, OUT));
